export default function Profile(){

const user=JSON.parse(

localStorage.getItem("user")

);

return(

<div style={style}>

<h1>👤 Profile</h1>

<h2>

Name :

{user?.name}

</h2>

<h2>

Email :

{user?.email}

</h2>

<h2>

Role :

{user?.role}

</h2>

</div>

)

}

const style={

padding:"50px",

textAlign:"center"

}
